const DICT = { en: new Map(), ja: new Map(), zh: new Map(), ru: new Map() };
for (const [ko, en, ja, zh, ru] of ENTRIES) { DICT.en.set(ko, en); DICT.ja.set(ko, ja); DICT.zh.set(ko, zh); DICT.ru.set(ko, ru); }
export const KEYS = ENTRIES.map(e => e[0]);       // (for the build check: every tr() key is here)
export const GAPS = ENTRIES.filter(e => e.length < LANGS.length || e.some(t => !t)).map(e => e[0]);   // (and in every language)

export function tr(ko, vars) {
  let s = current === 'ko' ? ko.split('|')[0] : (DICT[current]?.get(ko) ?? ko.split('|')[0]);
  if (vars) s = s.replace(/\{(\w+)\}/g, (m, k) => (k in vars ? String(vars[k]) : m));
  return s;
}
